  const PHOTOS = [{"src": "/terroir/Barcelona-Catalunya/img/cat-1-vermut-hour-as-a-communa.jpg", "caption": "Vermut hour as a communal ritual (the Catalan Sunday aperitif, not a staged terrace)", "credit": "GinaQA · CC BY-SA 3.0"}, {"src": "/terroir/Barcelona-Catalunya/img/cat-2-the-boqueria-counters-fr.jpg", "caption": "The Boqueria counters from the inside (greengrocer stalls, not the Rambla entrance)", "credit": "Böhringer Friedrich · CC BY-SA 2.5"}, {"src": "/terroir/Barcelona-Catalunya/img/cat-3-a-barcelona-tapas-pintxo.jpg", "caption": "A Barcelona tapas/pintxos bar spread on the counter", "credit": "Elemaki (José Porras) · CC BY 3.0"}];
  const GEMS = [{"id": "gem-pa-amb-tomaquet", "pattern": "pa amb tomàquet", "tag": "Barcelona gem · the table's opening", "name": "Bread rubbed red", "story": "Bread, oil and salt are ancient; the tomato is not. It came from the Americas, so the rubbed slice cannot be older than the sixteenth century, and the first written mention anyone has found is from the 1880s. Thrift is the usual account — late-summer tomatoes pressed into stale bread — and the origin stays undocumented.", "where": "Quimet & Quimet in Poble Sec, under the conservas."}, {"id": "gem-bomba", "pattern": "the bomba", "tag": "Barcelona gem · born here", "name": "The bomba of Barceloneta", "story": "A fist of mashed potato round spiced meat, breaded, fried and capped with a red hot sauce and white allioli. The credit goes to María Pla at La Cova Fumada, the unsigned Barceloneta tavern open since 1944, and the plate is usually dated to the 1950s: cheap fuel for the dock. Every bar in the city copies it now.", "where": "La Cova Fumada, Carrer del Baluard, Barceloneta."}, {"id": "gem-crema-catalana", "pattern": "crema catalana", "tag": "Barcelona gem · the oldest custard", "name": "Burnt cream, or not", "story": "Set with cornstarch and milk rather than cream, scented with cinnamon stick and lemon peel, then struck with a hot iron until the sugar cracks: that is the Catalan method, and the iron is the test of a kitchen that still makes it by hand. Whether the burnt top is older here than in France is the city's favourite food quarrel; The Dish, at the foot, has both sides.", "where": "Can Culleretes, the city's oldest dining room."}, {"id": "gem-parellada", "pattern": "arròs Parellada", "tag": "Barcelona gem · born here", "name": "The rice for a man who would not peel", "story": "Every prawn shelled, every bone lifted, so the diner touches nothing: the 'lazy man's rice' is said to have been made around 1902 for the Barcelona dandy Juli Maria Parellada. 7 Portes made it its signature; its proprietor from 1942, Paco Parellada, was no relation. The shared name is coincidence.", "where": "7 Portes on the Passeig d'Isabel II."}, {"id": "gem-cacaolat", "pattern": "Cacaolat", "tag": "Barcelona gem · born here", "name": "The chocolate milk of the Raval", "story": "The Viader family's granja on Carrer d'en Xuclà, open since 1870, is the reputed birthplace of Cacaolat, the bottled chocolate milk the whole of Spain knows. The room still pours a spoon-thick hot chocolate under whipped cream, the suizo. The brand left the family long ago; the granja did not.", "where": "Granja M. Viader, Carrer d'en Xuclà, Raval."}, {"id": "gem-panellets", "pattern": "panellets", "tag": "Barcelona gem · All Saints", "name": "Almond for the dead", "story": "Little balls of almond paste and sugar rolled in pine nuts and baked, eaten for Tots Sants on 1 November with roast chestnuts and sweet wine. They began as blessed food for the vigil of the dead, and the Baró de Maldà saw them sold on Barcelona's streets in autumn around 1800. The proverb fixes the season: per Tots Sants, castanyes i panellets.", "where": "Escribà on the Rambla, in late October."}, {"id": "gem-forquilla", "pattern": "esmorzar de forquilla", "tag": "Barcelona gem · the morning", "name": "Breakfast with a fork", "story": "Not coffee and a croissant but a real meal at ten: stews, tripe, botifarra and cap-i-pota, with wine from a porró, for farmers, dockers and market porters who had started at dawn. The name is often pinned on the writer Josep Pla; that is affectionate lore, not record. The city has lately reclaimed it against imported brunch.", "where": "The bars inside the markets, mid-morning."}];
  const TABLES = {"grande": {"title": "Les Grandes Tables", "desc": "The tables you clear an evening for — and book before you fly: the three-star houses, the elBulli line, and three two-star rooms that each speak a different accent.", "sections": [{"label": "La Crème — the three-star houses", "desc": "The three-star rooms: the 2024 world No. 1, the kitchen in the middle of the room, and the city's first three stars.", "ids": ["v01-disfrutar", "v04-cocina-hermanos-torres", "v02-lasarte"]}, {"label": "The elBulli line", "desc": "Albert Adrià's one surviving room, his old head chef's counter, and the bistro that put a tartare on a marrow bone.", "ids": ["v03-enigma", "vn-dos-palillos", "v15-suculent"]}, {"label": "Two stars, three accents", "desc": "Snacks first at Mont Bar, Cádiz in a Modernista house, and a self-taught chef's Catalan seasons.", "ids": ["v05-mont-bar", "v06-aleia", "v08-cinc-sentits"]}]}, "petite": {"title": "Les Petites Tables", "desc": "Where this guide actually lives: the new guard, the dated houses, the tapas counters, the sea quarters, the vermut bodegas, the wine rooms and the granjas.", "sections": [{"label": "The new guard — this year's star and Bibs", "desc": "This year's news: a first star in a 28-seat room, and two young rooms with their first Bib.", "ids": ["vr-kamikaze", "vr-glug", "vr-oniric"]}, {"label": "The old houses — dated", "desc": "1786, 1836, 1897: the canelons, the rice with no shells, and the café where Picasso first showed.", "ids": ["v09-can-culleretes", "v10-7-portes-set-portes", "vn-els-quatre-gats"]}, {"label": "At the counter — the tapas bars", "desc": "Sit at the bar or stand: the open kitchen in the Raval, the no-menu seafood counter, the 1914 montadito bodega.", "ids": ["v07-bar-ca-ete", "vn-cal-pep", "v11-quimet-quimet"]}, {"label": "The sea quarters — Barceloneta & Poblenou", "desc": "Where the bomba was born, the beer hall of 1962, and the Poblenou rice house.", "ids": ["v12-la-cova-fumada", "vn-el-vaso-de-oro", "v14-els-pescadors"]}, {"label": "L'hora del vermut — the bodegas", "desc": "The house fizz of 1929, a Gràcia bodega of 1954, and the 2007 bar that remade the ritual.", "ids": ["v13-el-xampanyet", "vc-bar-bodega-quimet", "vc-morro-fi"]}, {"label": "The wine rooms", "desc": "Three hundred bottles at the Eixample counter, the natural-wine cathedral, and shelf price plus corkage.", "ids": ["vn-bar-mut", "vc-can-cisa-bar-brutal", "vc-els-sortidors-del-parlament"]}, {"label": "Granjas & the sweet hour", "desc": "Cacaolat's birthplace, the convents' sweets, and the Modernista pastry shop on the Rambla.", "ids": ["vc-granja-m-viader", "vn-caelum", "vn-pastisseria-escriba-antiga-c"]}]}, "street": {"title": "La Rue — The Street", "desc": "Standing up: one thing done for decades at a marble counter, and the quick plate.", "sections": [{"label": "Standing up — one thing, done for decades", "desc": "Four tapas since 1945, a euro glass of cava since 1969, and the bravas worth the climb to Sarrià.", "ids": ["vc-bar-la-plata", "vc-can-paixano-la-xampanyeria", "vn-bar-tomas-el-tomas-de-sarria"]}, {"label": "The quick plate", "desc": "The 2010 burger pioneer, and the 1970 tortilla room.", "ids": ["vq-bacoa-kiosko-little-bacoa", "vc-flash-flash"]}]}};
  const CATEGORIES = [{"key": "creme", "label": "La Crème — the three-star houses", "lead": "The three-star rooms: the 2024 world No. 1, the kitchen in the middle of the room, and the city's first three stars.", "story": {"title": "Four houses, three stars each", "story": "Barcelona went into the 2026 MICHELIN guide with four three-star kitchens and came out with the same four; no new third star was given anywhere in Spain. Three are in this lane. Lasarte, in the Monument Hotel, was the city's first, in 2017, cooked by Paolo Casagrande under Martín Berasategui's name. Cocina Hermanos Torres took its third in November 2022 and seats diners around the cooking stations in Les Corts. Disfrutar, opened in 2014 by three former elBulli chefs, added its third in 2023 and was voted the World's Best Restaurant in 2024. The fourth, ABaC, sits uptown and is outside this guide.", "where": "Disfrutar on Carrer de Villarroel; Cocina Hermanos Torres on Carrer del Taquígraf Serra; Lasarte on Carrer de Mallorca"}}, {"key": "elbulli", "label": "The elBulli line", "lead": "Albert Adrià's one surviving room, his old head chef's counter, and the bistro that put a tartare on a marrow bone.", "story": {"title": "After elBulli closed", "story": "When elBulli shut in 2011, its cooks scattered across Barcelona, and several of their rooms are still here. Albert Adrià, the pastry chief, kept only Enigma after the pandemic took his other restaurants; it won a second star in November 2025. Albert Raurich, head chef until 2007, opened Dos Palillos in the Raval in 2008, a counter cooking Spanish ideas through Japan, and in 2026 the Repsol Guide gave it a second Sun. Toni Romero, who worked the meat line to the last service, opened Suculent on the Rambla del Raval in 2012, where the marrow-bone tartare has stayed on the menu ever since.", "where": "Enigma on Carrer de Sepúlveda; Dos Palillos on Carrer d'Elisabets; Suculent on Rambla del Raval"}}, {"key": "two-stars", "label": "Two stars, three accents", "lead": "Snacks first at Mont Bar, Cádiz in a Modernista house, and a self-taught chef's Catalan seasons.", "story": {"title": "Two stars, three accents", "story": "Barcelona has five two-star restaurants after the 2026 guide, and three of them are here, each with a different accent. Mont Bar on Diputació still works as a bar: MICHELIN notes an a la carte that asks for three snacks and two mains, and the second star came in November 2025. Aleia, upstairs in Casa Fuster, is cooked by Jerez-born Rafa de Bedoya, who puts Cádiz piriñaca under Palamós prawns; its second star came the same night. Cinc Sentits on Entença has held two since the end of 2020, run by self-taught Jordi Artal and his sister since 2004.", "where": "Mont Bar on Carrer de la Diputació; Aleia on Passeig de Gràcia; Cinc Sentits on Carrer d'Entença"}}, {"key": "rising", "label": "The new guard — this year's star and Bibs", "lead": "This year's news: a first star in a 28-seat room, and two young rooms with their first Bib.", "story": {"title": "The class of 2026", "story": "The November 2025 MICHELIN gala gave Catalonia only two new one-stars, both in Barcelona, and one went to Kamikaze, a 28-seat room on Rosselló that opened in 2022 as a vermouth bar and now serves Japanese-Mediterranean tasting menus from about EUR 75. The same guide added new Bib Gourmands in the city, among them Glug, a long-bar wine canteen run by two chefs opposite the Sant Jordi pool, open since June 2024, and Oníric, a six-table room in Gràcia whose menus run from EUR 18 to 36 depending on the sitting. All three are run by cooks who trained in the city's starred kitchens.", "where": "Kamikaze on Carrer del Rosselló; Glug on Carrer de Viladomat; Oníric on Carrer de Rabassa"}}, {"key": "houses", "label": "The old houses — dated", "lead": "1786, 1836, 1897: the canelons, the rice with no shells, and the café where Picasso first showed.", "story": {"title": "Old rooms, dated menus", "story": "Barcelona's oldest tables are dated by their founding years more than their cooking. Can Culleretes started in 1786 as a chocolate house off the Rambla, has been with the Agut-Manubens family since 1958, and serves its canelons, made since the 1950s, at a set lunch of about EUR 22. 7 Portes opened as a café in 1836 under the Xifré arcades, became a restaurant in 1929, and still seats diners across its salons; the shell-free rice is named for a regular, Juli Parellada. Els Quatre Gats, opened in 1897, gave Picasso his first solo show, and in 2026 its owners brought back pig's trotters and broths.", "where": "Can Culleretes on Carrer de Quintana; 7 Portes on Passeig d'Isabel II; Els Quatre Gats on Carrer de Montsió"}}, {"key": "counters", "label": "At the counter — the tapas bars", "lead": "Sit at the bar or stand: the open kitchen in the Raval, the no-menu seafood counter, the 1914 montadito bodega.", "story": {"title": "Eating at the stove's edge", "story": "Barcelona's best tapas counters put the diner a stool's width from the cook, and the meal is part watching. At Bar Cañete on Carrer de la Unió, a Sevillian family line and the Olivé group run an Andalusian bar where tortillitas de camarones come straight from the oil and jamón is carved within reach; MICHELIN lists it. At Cal Pep on Plaça de les Olles, open since 1989, there is no printed menu: the cooks decide and plate in sequence. Quimet & Quimet in Poble-sec, a family bodega since 1914, has no stools at all, and every montadito is built from the tins stacked on its walls.", "where": "Bar Cañete on Carrer de la Unió; Cal Pep on Plaça de les Olles; Quimet & Quimet on Carrer del Poeta Cabanyes"}}, {"key": "sea", "label": "The sea quarters — Barceloneta & Poblenou", "lead": "Where the bomba was born, the beer hall of 1962, and the Poblenou rice house.", "story": {"title": "Fishermen's quarters, fishermen's food", "story": "Barceloneta was laid out in the eighteenth century for fishermen and port workers, and Poblenou grew up beside the factories and the shore; their tables still cook for appetites like those. La Cova Fumada, a signless tavern from 1944, is where the grandmother of the house invented the bomba in the 1950s. El Vaso de Oro, opened in 1962, pours the family's own Fort beer and earns a Guía Repsol Solete for its solomillo con foie. In Poblenou, Els Pescadors has cooked rice and fish since 1980 in a fishermen's tavern dating to 1913, on a square shaded by ombú trees.", "where": "La Cova Fumada on Carrer del Baluard; El Vaso de Oro on Carrer de Balboa; Els Pescadors on Plaça de Prim"}}, {"key": "vermut", "label": "L'hora del vermut — the bodegas", "lead": "The house fizz of 1929, a Gràcia bodega of 1954, and the 2007 bar that remade the ritual.", "story": {"title": "The Sunday-noon vermut hour", "story": "In Barcelona 'fer el vermut' means a glass of sweet red vermut before lunch, usually at weekend noon, with tins and olives, and the bodegas that served it never stopped. El Xampanyet in El Born, opened in 1929, took its name from its own cloudy sparkling wine and is run by the founder's granddaughters. Bar Bodega Quimet in Gràcia kept its barrels and marble tables when the Montero brothers took over in 2010. Morro Fi began as a 2007 blog by three friends rating aperitiu bars, and opened its own standing bar on Consell de Cent in 2011.", "where": "El Xampanyet on Carrer de Montcada; Bar Bodega Quimet on Carrer de Vic; Morro Fi on Carrer del Consell de Cent"}}, {"key": "wine", "label": "The wine rooms", "lead": "Three hundred bottles at the Eixample counter, the natural-wine cathedral, and shelf price plus corkage.", "story": {"title": "Bottles off the wall", "story": "Barcelona's wine rooms often blur shop and bar: you choose from the shelves and drink at close to retail price. Bar Mut, opened in June 2005 by Kim Díaz on Pau Claris, keeps more than 300 bottles behind a marble counter and writes its food on a daily chalkboard. Can Cisa and Bar Brutal in El Born opened in 2013 as one of the city's first natural-wine rooms, with Venetian twins Max and Stefano Colombo cooking. Els Sortidors del Parlament, in a former Sant Antoni motorbike workshop, sells bottles at shop price plus corkage, drunk over upturned barrels.", "where": "Bar Mut on Carrer de Pau Claris; Can Cisa / Bar Brutal on Carrer de la Princesa; Els Sortidors del Parlament on Carrer del Parlament"}}, {"key": "granja", "label": "Granjas & the sweet hour", "lead": "Cacaolat's birthplace, the convents' sweets, and the Modernista pastry shop on the Rambla.", "story": {"title": "Thick chocolate, afternoon hour", "story": "A granja was a dairy bar, selling milk, cream and curd cheese, and the survivors became the city's places for thick hot chocolate in the late afternoon. Granja M. Viader has traded on Carrer d'en Xuclà since 1870; the family patented Cacaolat there in 1931, and a fifth-generation owner took over in May 2026. Caelum, in the Gothic Quarter, sells sweets made in Spanish convents and serves chocolate in a vaulted basement over medieval baths. On La Rambla, Escribà runs a pastry counter in the 1902 modernista shopfront of the Antiga Casa Figueras.", "where": "Granja M. Viader on Carrer d'en Xuclà; Caelum on Carrer de la Palla; Escribà on La Rambla"}}, {"key": "standing", "label": "Standing up — one thing, done for decades", "lead": "Four tapas since 1945, a euro glass of cava since 1969, and the bravas worth the climb to Sarrià.", "story": {"title": "One plate, decades deep", "story": "Some Barcelona bars have served the same short list for generations and are crowded because of it. Bar La Plata, opened in 1945 near the port, offers four tapas only: fried small fish, anchovies, botifarra and a tomato salad, with barrel wine from Penedès. Can Paixano, since 1969 by Port Vell, pours its own pink cava to a crowd standing between hanging hams, with a botifarra roll from the grill. Up in Sarrià, Bar Tomás has served bravas since 1929 under allioli and chilli oil rather than red sauce, and Time Out ranks them among the city's best.", "where": "Bar La Plata on Carrer de la Mercè; Can Paixano on Carrer de la Reina Cristina; Bar Tomás on Carrer Major de Sarrià"}}, {"key": "quick", "label": "The quick plate", "lead": "The 2010 burger pioneer, and the 1970 tortilla room.", "story": {"title": "Burgers and tortillas, fast", "story": "The quick plate in Barcelona runs from the tortilla bar to the burger counter. Flash Flash, opened in 1970 by photographer Leopoldo Pomés with architect Alfonso Milà, serves more than fifty tortillas in a white room lined with silhouettes cut from Pomés's photographs of the model Karin Leiz; it is open late every day. Bacoa started in 2010 as a 15-seat counter behind the Santa Caterina market, where Brad Ainsworth grilled burgers over stone and won Time Out Barcelona's best-sandwich award; AmRest bought the chain in 2018 and the original site is listed closed.", "where": "Flash Flash on Carrer de la Granada del Penedès; Bacoa Kiosko on Avinguda del Marquès de l'Argentera"}}];
  const GROUPS = [{"key": "grande", "label": "Les Grandes Tables", "lead": "The tables you clear an evening for — and book before you fly: the three-star houses, the elBulli line, and three two-star rooms that each speak a different accent."}, {"key": "petite", "label": "Les Petites Tables", "lead": "Where this guide actually lives: the new guard, the dated houses, the tapas counters, the sea quarters, the vermut bodegas, the wine rooms and the granjas."}, {"key": "street", "label": "La Rue — The Street", "lead": "Standing up: one thing done for decades at a marble counter, and the quick plate."}];
